onClick:
{{
  Action_Supprimer_Client.run().then((res) => {
    // res[0].total_lignes contient le résultat du calcul de la base de données
    if (res[0].total_lignes > 0) {
      showAlert('Client archivé (il possédait un historique).', 'info');
    } else {
      showAlert('Client supprimé définitivement.', 'success');
    }

    // On ferme la modale
    closeModal('modal_delete_client');

    // On redirige vers la liste des clients (Remplace 'Page_Clients' par le nom exact de ta page)
    navigateTo('Page_Clients');
  }).catch(() => {
    showAlert('Erreur lors de la suppression/archivage', 'error');
  });
}}
